def _表述冫文本巛溟母链扌(溟母链, /):
    #文本表达{溟母链}:[j:num_ezs,...;... ...]
    if not len(溟母链) >= 1:raise TypeError
    def __():
        yield '['
        for 汇址, 劫纟溟母链 in enumerate(溟母链):
            if 汇址 == 0:
                assert len(劫纟溟母链) == 0
            else:
                yield ';'
                b_fst = True
                for 源址, 源溟数 in 劫纟溟母链:
                    if b_fst:
                        b_fst = False
                    else:
                        yield ','
                    yield f'{源址}:{源溟数}'
        yield ']'
    return ''.join(__())
def 解读冫文本讠溟母链扌(文本, /):
    溟母链 = _解读冫文本讠溟母链扌(文本)
    检查冫溟母链扌(溟母链)
    if not 文本 == (__:=_表述冫文本巛溟母链扌(溟母链)):raise Exception(文本, 溟母链, __)
    return 溟母链
def _解读冫文本讠溟母链扌(文本, /):
    check_type_is(str, 文本)
    if not 文本.startswith('['):raise ValueError([文本])
    if not 文本.endswith(']'):raise ValueError
    ss = 文本[1:-1].split(';')
    if not ss[0] == '':raise ValueError
    def f(s, /):
        if not s:
            return
        for _s_ in s.split(','):
            (j, num_ezs) = _s_.split(':')
            j = int(j)
            num_ezs = int(num_ezs)
            yield (j, num_ezs) # (源址, 源溟数)
    溟母链 = tuple(tuple(f(s)) for s in ss)
    return 溟母链


def 检查冫溟母链扌(溟母链, /):
    _检查类型冫溟母链扌(溟母链)
    检查内容冫溟母链扌(溟母链)
def _检查类型冫溟母链扌(溟母链, /):
    check_type_is(tuple, 溟母链)
    for 汇址, 劫纟溟母链 in enumerate(溟母链):
        check_type_is(tuple, 劫纟溟母链)
        for 源址溟数 in 劫纟溟母链:
            check_pair(源址溟数)
            (源址, 源溟数) = 源址溟数
            check_int_ge_lt(0, 汇址, 源址)
            check_int_ge(1, 源溟数)

def 检查内容冫溟母链扌(溟母链, /):
    if not len(溟母链) >= 1:raise TypeError
    for 汇址, 劫纟溟母链 in enumerate(溟母链):
        for (源址, 源溟数) in 劫纟溟母链:
            check_int_ge_lt(0, 汇址, 源址)
            check_int_ge(1, 源溟数)

    末汇址 = -1+len(溟母链)
    for 汇址, 劫纟溟母链 in enumerate(溟母链):
        if 汇址 == 0:
            if not len(劫纟溟母链) == 0:raise TypeError
        else:
            if not len(劫纟溟母链) >= 1:raise TypeError
            if not len(劫纟溟母链) >= 2 or (len(劫纟溟母链) == 1 and (源溟数:=劫纟溟母链[0][1]) >= 1 and (源溟数 >= 2 or (源溟数 == 1 and 汇址 == 末汇址))):raise TypeError
                #入度大于一{非首劫}
                #尾部可能是二幂环

    if not all(劫[0][0] <= 后一劫[0][0] for 劫, 后一劫 in pairwise(溟母链[1:])):raise TypeError
        #松序升列:key=at[0][0]
        #劫首源址松序递升
    if not all(源址 > 后一源址 for 劫纟溟母链 in 溟母链 for (源址, _), (后一源址, _) in pairwise(劫纟溟母链)):raise TypeError
        #严序降列:key=fst
        #源址严序递降


def _归组冫溟母链讠靶值集巛最短加链讠溟母链扌(may_max1=None):
    from nn_ns.math_nn.numbers.shortest_recursive_addition_chain__the_min_and_max_if_revered import pint2revmin_shortest_recursive_addition_chain, pint2revmax_shortest_recursive_addition_chain as 靶值讠最短加链
    靶值讠最短加链 = 靶值讠最短加链[:may_max1]
    溟母链讠靶值集 = {}
    for 靶值, 最短加链 in enumerate(靶值讠最短加链):
        if 靶值 == 0:continue
        溟隘链 = 缩写冫最短加链讠溟隘链扌(最短加链)
        溟母链 = 缩写冫溟隘链讠溟母链扌(溟隘链)
        溟母链讠靶值集.setdefault(溟母链, []).append(靶值)
    txt_us_pairs = sorted((表述冫文本巛溟母链扌(溟母链), 靶值集) for 溟母链, 靶值集 in 溟母链讠靶值集.items())
    num_us2num_groups = {}
    for txt, us in txt_us_pairs:
        num_us = len(us)
        num_groups = num_us2num_groups.setdefault(num_us, 0)
        num_us2num_groups[num_us] = 1+num_groups
    num_us2num_groups
    num_us = -1+len(靶值讠最短加链)
    num_groups = len(txt_us_pairs)

    yield (num_us, num_groups, num_us2num_groups)
    yield from map(fst, txt_us_pairs)
    yield from txt_us_pairs
    return

